{
  "claims": [
    {
      "text": "Order packed red blood cell transfusion to raise hemoglobin.",
      "action_type": "ordered",
      "target": "PRBC transfusion"
    },
    {
      "text": "Continue pantoprazole infusion for ulcer prophylaxis.",
      "action_type": "ordered",
      "target": "Pantoprazole 40 mg IV continuous"
    },
    {
      "text": "Monitor hemoglobin and hematocrit q6h to assess response to therapy.",
      "action_type": "monitored",
      "target": "Hemoglobin/hematocrit levels"
    }
  ]
}

{
  "claims": [
    {
      "text": "Administer platelet transfusion to address thrombocytopenia (platelet count 45 K/µL).",
      "action_type": "administered",
      "target": "Platelet transfusion"
    },
    {
      "text": "Monitor serum magnesium and replace if below 1.5 mg/dL.",
      "action_type": "monitored",
      "target": "Magnesium level"
    },
    {
      "text": "Continue PRN lorazepam dosing for alcohol withdrawal symptom control.",
      "action_type": "ordered",
      "target": "Lorazepam PRN"
    }
  ]
}

{
  "claims": [
    {
      "text": "Order packed red blood cell transfusion to treat anemia (Hb 7.7‑8.9 g/dL).",
      "action_type": "ordered",
      "target": "packed red blood cells transfusion"
    },
    {
      "text": "Start intravenous labetalol infusion for persistent hypertension (SBP 148‑184 mmHg).",
      "action_type": "ordered",
      "target": "IV labetalol infusion"
    },
    {
      "text": "Continue close hemodynamic monitoring with arterial line MAP and frequent blood pressure checks.",
      "action_type": "monitored",
      "target": "arterial line MAP and non‑invasive blood pressure"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain INR to monitor warfarin therapy and adjust dose as needed.",
      "action_type": "specimen_collected",
      "target": "INR"
    },
    {
      "text": "Assess pain level regularly and titrate opioid analgesics to maintain pain score ≤3.",
      "action_type": "monitored",
      "target": "pain assessment"
    },
    {
      "text": "Schedule physical therapy evaluation to begin early mobilization.",
      "action_type": "ordered",
      "target": "physical therapy assessment"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain a repeat 12-lead electrocardiogram to assess rhythm control and QT interval after ibutilide administration.",
      "action_type": "assessment_performed",
      "target": "ECG"
    },
    {
      "text": "Continue intravenous diltiazem infusion at the current rate and monitor blood pressure and heart rate q1h.",
      "action_type": "monitored",
      "target": "diltiazem infusion"
    },
    {
      "text": "Order a transthoracic echocardiogram to evaluate cardiac function and rule out structural contributors to supraventricular tachyarrhythmia.",
      "action_type": "imaging_performed",
      "target": "transthoracic echocardiogram"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain a repeat arterial blood gas to assess ongoing ventilation status and guide weaning from non‑invasive ventilation.",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    },
    {
      "text": "Continue current non‑invasive ventilation settings and monitor respiratory parameters closely for the next 4–6 hours.",
      "action_type": "monitored",
      "target": "non‑invasive ventilation"
    },
    {
      "text": "Order a chest radiograph to evaluate for possible infiltrates or atelectasis given persistent respiratory symptoms.",
      "action_type": "imaging_performed",
      "target": "chest X‑ray"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain a repeat INR measurement to assess warfarin anticoagulation effectiveness.",
      "action_type": "specimen_collected",
      "target": "INR"
    },
    {
      "text": "Adjust warfarin dose based on the repeat INR result to achieve therapeutic range for pulmonary embolism.",
      "action_type": "ordered",
      "target": "warfarin dose adjustment"
    },
    {
      "text": "Continue low molecular weight heparin (enoxaparin) as a bridge until therapeutic INR is confirmed.",
      "action_type": "treatment_performed",
      "target": "enoxaparin"
    }
  ]
}

{
  "claims": [
    {
      "text": "Order packed red blood cell transfusion to raise hemoglobin.",
      "action_type": "ordered",
      "target": "packed red blood cells transfusion"
    },
    {
      "text": "Continue intravenous meropenem therapy for broad‑spectrum coverage of possible intra‑abdominal infection.",
      "action_type": "ordered",
      "target": "meropenem"
    },
    {
      "text": "Obtain an emergent upper endoscopy to locate and control the source of gastrointestinal bleeding.",
      "action_type": "procedure_performed",
      "target": "upper endoscopy"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue ventilator weaning protocol with daily assessment of spontaneous breathing trials.",
      "action_type": "therapy_continued",
      "target": "ventilator_weaning"
    },
    {
      "text": "Monitor blood glucose q4h and adjust subcutaneous insulin detemir dose as needed to maintain target range.",
      "action_type": "monitored",
      "target": "blood_glucose"
    },
    {
      "text": "Check INR in 12 hours and adjust warfarin (coumadin) dosing to keep INR within therapeutic range (2.0‑3.0).",
      "action_type": "monitored",
      "target": "INR"
    }
  ]
}

{
  "claims": [
    {
      "text": "Begin continuous arterial blood pressure monitoring and obtain a lactate level to assess perfusion status.",
      "action_type": "monitored",
      "target": "arterial line placement and lactate measurement"
    },
    {
      "text": "Start norepinephrine infusion to maintain MAP ≥65 mmHg given persistent hypotension despite fluid bolus.",
      "action_type": "ordered",
      "target": "norepinephrine IV infusion"
    },
    {
      "text": "Transfuse packed red blood cells to address hemoglobin of 8 g/dL in the setting of sepsis.",
      "action_type": "ordered",
      "target": "packed red blood cell unit"
    }
  ]
}

{
  "claims": [
    {
      "text": "Order packed red blood cell transfusion to treat ongoing anemia (Hb 7.7‑8.1 g/dL) and maintain adequate oxygen delivery.",
      "action_type": "ordered",
      "target": "packed red blood cells transfusion"
    },
    {
      "text": "Obtain repeat complete blood count and coagulation panel in 6 hours to monitor trends in hemoglobin, hematocrit, platelets, PT/INR, and fibrinogen.",
      "action_type": "specimen_collected",
      "target": "repeat CBC and coagulation studies"
    },
    {
      "text": "Continue close hemodynamic monitoring (blood pressure, heart rate, SpO₂) and urine output charting to assess response to therapy and detect any further instability.",
      "action_type": "monitored",
      "target": "vital signs and urine output"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation with current settings (PEEP 5 cmH₂O, FiO₂ 50%) and monitor for readiness to wean as sedation is deepened.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Obtain a serum ammonia level trend and start lactulose orally to lower ammonia given the elevated value (87 µmol/L).",
      "action_type": "ordered",
      "target": "lactulose PO"
    },
    {
      "text": "Check bedside glucose hourly and adjust sliding‑scale insulin infusion to maintain glucose 80‑140 mg/dL.",
      "action_type": "monitored",
      "target": "blood glucose"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue intravenous nicardipine infusion with titration to maintain mean arterial pressure ≥65 mmHg.",
      "action_type": "ordered",
      "target": "Nicardipine IV infusion"
    },
    {
      "text": "Obtain repeat basic metabolic panel and complete blood count in the next 4 hours to monitor renal function, electrolytes, and hemoglobin trends.",
      "action_type": "specimen_collected",
      "target": "Blood laboratory studies"
    },
    {
      "text": "Monitor neurologic status and vital signs q1 hour, including GCS, blood pressure, and oxygen saturation.",
      "action_type": "monitored",
      "target": "Neurologic and hemodynamic parameters"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue non‑invasive ventilation with BiPAP and titrate FiO₂ to maintain SpO₂ ≥ 92 % while monitoring for respiratory fatigue.",
      "action_type": "therapy_continued",
      "target": "BiPAP ventilation"
    },
    {
      "text": "Obtain a repeat basic metabolic panel and renal function tests in the next 4 hours to reassess creatinine trend and electrolyte status.",
      "action_type": "specimen_collected",
      "target": "Basic metabolic panel"
    },
    {
      "text": "Administer IV furosemide 20 mg now and reassess urine output and volume status to guide further diuretic therapy.",
      "action_type": "ordered",
      "target": "IV furosemide"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue volume‑controlled mechanical ventilation with tidal volume 6‑8 mL/kg, FiO₂ 65‑70 % and PEEP 5‑7 cmH₂O.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Monitor point‑of‑care glucose q4h and adjust insulin sliding‑scale as needed.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Obtain arterial blood gas every 6 hours to assess ventilation and acid‑base status.",
      "action_type": "assessment_performed",
      "target": "arterial blood gas"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue non‑invasive ventilation with current settings and monitor respiratory parameters closely.",
      "action_type": "therapy_continued",
      "target": "non‑invasive ventilation"
    },
    {
      "text": "Obtain an arterial blood gas to assess oxygenation, ventilation, and acid‑base status.",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    },
    {
      "text": "Order a chest radiograph to evaluate for airway edema or other obstructive pathology.",
      "action_type": "imaging_performed",
      "target": "chest X‑ray"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain repeat blood cultures to assess ongoing bacteremia and guide antimicrobial therapy.",
      "action_type": "specimen_collected",
      "target": "blood culture"
    },
    {
      "text": "Administer a 500 mL crystalloid bolus to support borderline mean arterial pressure and improve tissue perfusion.",
      "action_type": "ordered",
      "target": "IV crystalloid bolus 500 mL normal saline"
    },
    {
      "text": "Continue current broad‑spectrum antibiotics (piperacillin‑tazobactam and vancomycin) and add levofloxacin as scheduled for extended Gram‑negative coverage.",
      "action_type": "ordered",
      "target": "continue antibiotics: ZOSYN, VANCOMYCIN, LEVOFLOXACIN"
    }
  ]
}

{
  "claims": [
    {
      "text": "Increase sodium bicarbonate infusion to target serum bicarbonate >22 mmol/L and correct metabolic acidosis.",
      "action_type": "ordered",
      "target": "Sodium Bicarbonate IV infusion"
    },
    {
      "text": "Titrate dobutamine infusion to maintain mean arterial pressure ≥65 mmHg.",
      "action_type": "monitored",
      "target": "Dobutamine infusion rate"
    },
    {
      "text": "Obtain repeat arterial blood gas and serum lactate in 2 hours to assess response to therapy.",
      "action_type": "specimen_collected",
      "target": "Arterial blood gas and lactate"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation with current settings and monitor respiratory parameters closely.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Obtain a repeat complete blood count in 6 hours to reassess platelet trend.",
      "action_type": "assessment_performed",
      "target": "complete blood count"
    },
    {
      "text": "Initiate a low-dose intravenous antihypertensive infusion (e.g., nicardipine) to target MAP 65‑75 mmHg.",
      "action_type": "ordered",
      "target": "antihypertensive infusion"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue intravenous amiodarone infusion and monitor serum electrolytes (especially potassium and magnesium) q4h.",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Obtain repeat arterial blood gas and lactate measurement in 2 hours to assess metabolic acidosis and tissue perfusion.",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    },
    {
      "text": "Gradually wean norepinephrine infusion as blood pressure stabilizes, targeting MAP ≥65 mmHg.",
      "action_type": "monitored",
      "target": "norepinephrine infusion"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain repeat blood cultures to assess ongoing bacteremia.",
      "action_type": "specimen_collected",
      "target": "blood culture"
    },
    {
      "text": "Continue current broad‑spectrum antibiotics (piperacillin‑tazobactam and vancomycin) pending culture results.",
      "action_type": "ordered",
      "target": "piperacillin‑tazobactam and vancomycin"
    },
    {
      "text": "Monitor serum lactate q6h to track response to sepsis therapy.",
      "action_type": "monitored",
      "target": "serum lactate"
    }
  ]
}

{
  "claims": [
    {
      "text": "Begin gradual weaning of epinephrine and phenylephrine infusions as mean arterial pressure stabilizes above 65 mmHg with adequate cardiac output.",
      "action_type": "monitored",
      "target": "vasopressor infusion rates"
    },
    {
      "text": "Assess readiness for spontaneous breathing trial and consider extubation if mental status improves (GCS ≥ 13) and ventilatory parameters remain stable.",
      "action_type": "assessment_performed",
      "target": "ventilator weaning trial"
    },
    {
      "text": "Obtain a repeat complete blood count and coagulation panel to evaluate ongoing anemia and thrombocytopenia.",
      "action_type": "specimen_collected",
      "target": "laboratory studies"
    }
  ]
}

{
  "claims": [
    {
      "text": "Transfuse packed red blood cells to address hemoglobin of 8.6 g/dL.",
      "action_type": "ordered",
      "target": "packed red blood cells"
    },
    {
      "text": "Administer platelet transfusion for platelet count of 82 K/MM³.",
      "action_type": "ordered",
      "target": "platelet concentrate"
    },
    {
      "text": "Monitor coagulation profile (PT/INR) and repeat CBC in 6 hours.",
      "action_type": "monitored",
      "target": "laboratory values"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue the IV diltiazem infusion to maintain rate control of atrial arrhythmia.",
      "action_type": "therapy_continued",
      "target": "Diltiazem infusion"
    },
    {
      "text": "Monitor blood pressure and heart rate q15 min while on diltiazem.",
      "action_type": "monitored",
      "target": "Vital signs (BP, HR)"
    },
    {
      "text": "Obtain a repeat ECG to assess rhythm response to antiarrhythmic therapy.",
      "action_type": "assessment_performed",
      "target": "Electrocardiogram"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain a repeat troponin I level to assess for ongoing myocardial injury.",
      "action_type": "specimen_collected",
      "target": "troponin I"
    },
    {
      "text": "Adjust insulin therapy by increasing the aspart insulin dose per sliding scale to target glucose <180 mg/dL.",
      "action_type": "ordered",
      "target": "aspart insulin sliding scale"
    },
    {
      "text": "Continue daily hemodialysis and monitor serum electrolytes (potassium, bicarbonate) each shift.",
      "action_type": "monitored",
      "target": "hemodialysis and electrolytes"
    }
  ]
}

{
  "claims": [
    {
      "text": "Increase norepinephrine infusion to maintain MAP ≥65 mmHg",
      "action_type": "ordered",
      "target": "Norepinephrine infusion rate"
    },
    {
      "text": "Obtain repeat hemoglobin and hematocrit in 2 hours to assess ongoing bleeding",
      "action_type": "specimen_collected",
      "target": "CBC"
    },
    {
      "text": "Continue close hemodynamic monitoring with arterial line and repeat lactate in 4 hours",
      "action_type": "monitored",
      "target": "Arterial blood pressure and lactate level"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue cardiac monitoring and frequent vital sign checks (q1h) to assess for hemodynamic instability.",
      "action_type": "monitored",
      "target": "vital signs"
    },
    {
      "text": "Order repeat serum electrolytes and renal panel in 6 hours to evaluate for evolving metabolic derangements.",
      "action_type": "specimen_collected",
      "target": "blood chemistry panel"
    },
    {
      "text": "Maintain therapeutic enoxaparin dosing and schedule the next subcutaneous dose per protocol.",
      "action_type": "ordered",
      "target": "enoxaparin subcutaneous qDay"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue norepinephrine infusion and titrate to maintain MAP ≥65 mmHg.",
      "action_type": "ordered",
      "target": "norepinephrine infusion"
    },
    {
      "text": "Monitor serum lactate q4h until it trends down to <2 mmol/L.",
      "action_type": "monitored",
      "target": "lactate level"
    },
    {
      "text": "Obtain repeat arterial blood gas to reassess acid‑base status and oxygenation.",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    }
  ]
}

{
  "claims": [
    {
      "text": "Start norepinephrine infusion to maintain MAP ≥65 mmHg.",
      "action_type": "ordered",
      "target": "norepinephrine IV infusion"
    },
    {
      "text": "Obtain repeat basic metabolic panel and lactate to assess renal function and perfusion.",
      "action_type": "specimen_collected",
      "target": "blood sample for BMP and lactate"
    },
    {
      "text": "Perform a repeat chest X‑ray to evaluate for evolving pulmonary infiltrates or effusion.",
      "action_type": "imaging_performed",
      "target": "chest radiograph"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue IV nicardipine infusion to maintain systolic blood pressure < 150 mmHg.",
      "action_type": "ordered",
      "target": "nicardipine IV infusion"
    },
    {
      "text": "Obtain serum acetylcholine receptor antibody titer to assess myasthenia gravis activity.",
      "action_type": "specimen_collected",
      "target": "blood sample for acetylcholine receptor antibody"
    },
    {
      "text": "Monitor blood pressure and heart rate every hour while on antihypertensive therapy.",
      "action_type": "monitored",
      "target": "vital signs (BP, HR)"
    }
  ]
}

{
  "claims": [
    {
      "text": "Start a low‑dose norepinephrine infusion to maintain mean arterial pressure ≥65 mmHg.",
      "action_type": "ordered",
      "target": "norepinephrine IV infusion"
    },
    {
      "text": "Continue subcutaneous heparin q12h for VTE prophylaxis.",
      "action_type": "ordered",
      "target": "heparin subcutaneous"
    },
    {
      "text": "Monitor invasive arterial blood pressure and lactate q2h.",
      "action_type": "monitored",
      "target": "arterial line blood pressure and serum lactate"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain a repeat bedside transthoracic echocardiogram to assess for re‑accumulation of pericardial fluid.",
      "action_type": "imaging_performed",
      "target": "repeat transthoracic echocardiogram"
    },
    {
      "text": "Continue hourly vital sign monitoring and invasive blood pressure checks given recent pericardiocentesis.",
      "action_type": "monitored",
      "target": "vital signs and invasive blood pressure"
    },
    {
      "text": "Measure and record pericardial drainage catheter output every hour.",
      "action_type": "procedure_performed",
      "target": "pericardial drainage catheter output measurement"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain repeat complete blood count and coagulation panel to reassess anemia and anticoagulation effect.",
      "action_type": "specimen_collected",
      "target": "CBC and coagulation studies"
    },
    {
      "text": "Adjust heparin infusion to a lower rate pending repeat PTT and consider holding if bleeding risk increases.",
      "action_type": "ordered",
      "target": "Heparin infusion rate adjustment"
    },
    {
      "text": "Administer packed red blood cells if hemoglobin remains <8 g/dL after repeat labs.",
      "action_type": "administered",
      "target": "PRBC transfusion"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue milrinone infusion for inotropic support.",
      "action_type": "treatment_performed",
      "target": "milrinone infusion"
    },
    {
      "text": "Obtain an arterial blood gas to assess acid‑base status and lactate.",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    },
    {
      "text": "Monitor capillary glucose q4h and adjust insulin aspart dosing per protocol.",
      "action_type": "monitored",
      "target": "blood glucose"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue propofol infusion to maintain target RASS of -5 for deep sedation.",
      "action_type": "therapy_continued",
      "target": "propofol infusion"
    },
    {
      "text": "Increase norepinephrine infusion to support mean arterial pressure >65 mmHg.",
      "action_type": "ordered",
      "target": "norepinephrine infusion"
    },
    {
      "text": "Obtain arterial blood gas to assess ventilation and acid‑base status while on mechanical ventilation.",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation with current settings and monitor respiratory parameters.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Obtain a chest radiograph to assess for pulmonary infiltrates or complications.",
      "action_type": "imaging_performed",
      "target": "chest X-ray"
    },
    {
      "text": "Monitor serum sodium and consider correction if hyponatremia persists.",
      "action_type": "monitored",
      "target": "serum sodium level"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue intravenous antihistamine infusion for ongoing anaphylaxis management.",
      "action_type": "ordered",
      "target": "IV antihistamine (e.g., diphenhydramine) infusion"
    },
    {
      "text": "Start a short course of intravenous corticosteroids to prevent delayed biphasic reaction.",
      "action_type": "ordered",
      "target": "IV methylprednisolone"
    },
    {
      "text": "Monitor serum glucose hourly and initiate insulin infusion if glucose remains >250 mg/dL.",
      "action_type": "monitored",
      "target": "Blood glucose level"
    }
  ]
}

{
  "claims": [
    {
      "text": "Order packed red blood cell transfusion to address hemoglobin ~8.5 g/dL with ongoing respiratory distress.",
      "action_type": "ordered",
      "target": "packed red blood cells transfusion"
    },
    {
      "text": "Continue non‑invasive ventilation with close monitoring of respiratory rate and oxygen saturation.",
      "action_type": "therapy_continued",
      "target": "non‑invasive ventilation"
    },
    {
      "text": "Obtain repeat arterial blood gas to reassess PaO₂/FiO₂ ratio and acid‑base status.",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    }
  ]
}

{
  "claims": [
    {
      "text": "Titrate norepinephrine infusion to maintain mean arterial pressure ≥65 mmHg.",
      "action_type": "ordered",
      "target": "norepinephrine infusion"
    },
    {
      "text": "Obtain blood cultures and a repeat lactate level to assess ongoing sepsis.",
      "action_type": "specimen_collected",
      "target": "blood cultures and lactate"
    },
    {
      "text": "Assess readiness for spontaneous breathing trial and consider weaning from mechanical ventilation.",
      "action_type": "assessment_performed",
      "target": "spontaneous breathing trial"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation with current settings and assess readiness for weaning in the next 4–6 hours.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Obtain arterial blood gas to monitor pH, pCO₂, and pO₂ trends while on FiO₂ 35% and PEEP 5 cm H₂O.",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    },
    {
      "text": "Monitor hemodynamics (blood pressure, heart rate) and urine output closely; adjust intravenous fluid rate as needed to maintain MAP >65 mmHg.",
      "action_type": "monitored",
      "target": "hemodynamic status"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain repeat serum lactate and basic metabolic panel to assess for ongoing perfusion deficits and renal function.",
      "action_type": "specimen_collected",
      "target": "blood"
    },
    {
      "text": "Order an abdominal CT scan with contrast to evaluate for postoperative complications such as anastomotic leak or intra‑abdominal abscess.",
      "action_type": "imaging_performed",
      "target": "abdominal CT"
    },
    {
      "text": "Continue current broad‑spectrum antibiotic regimen and reassess culture results for potential de‑escalation.",
      "action_type": "treatment_performed",
      "target": "antibiotics"
    }
  ]
}

{
  "claims": [
    {
